sample_for <- c(
  Original = "knight",
  Sepia = "rider",
  Vignette = "statue",
  Grain = "samurai",
  Faded = "rider",
  Noir = "samurai",
  Duotone = "tiger",
  Vintage = "car",
  Warm = "tiger",
  Cool = "rider",
  Dramatic = "knight",
  Bright = "statue",
  Moody = "spartan",
  Negative = "statue",
  Poster = "tiger",
  Blur = "car",
  Cyanotype = "knight",
  Sunset = "car",
  Emboss = "samurai",
  Sketch = "spartan",
  Pixelate = "spartan"
)

render_samples <- function() {
  pics <- lapply(sample_images, function(x) {
    image_read(base64enc::base64decode(paste(x, collapse = "")))
  })
  for (i in seq_along(filter_names)) {
    fn  <- filter_names[i]
    img <- pics[[ sample_for[[fn]] ]]
    out <- tryCatch(apply_filter_by_name(img, fn, 1), error = function(e) img)
    image_write(out, path = file.path(art_dir, sprintf("sample-%02d.jpg", i)),
                format = "jpeg", quality = 82)
  }
}
render_samples()

shinyApp(ui = ui, server = server)